import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const n = Number(input[0]);
const MOD = 1_000_000_007n;
const graph: number[][] = Array.from({ length: n + 1 }, () => []);
for (let i = 1; i < n; i++) {
  const [u, v] = input[i].split(" ").map(Number);
  graph[u].push(v);
  graph[v].push(u);
}

// 頂点 1 を根として BFS 順を求める。逆順に処理すれば子が先に計算される
const parent = new Int32Array(n + 1);
const order = [1];
parent[1] = -1;
for (let head = 0; head < order.length; head++) {
  const v = order[head];
  for (const next of graph[v]) {
    if (next === parent[v]) continue;
    parent[next] = v;
    order.push(next);
  }
}

// white[v], black[v] = v を白・黒に塗ったとき、v の部分木の塗り方の数
const white = new Array<bigint>(n + 1).fill(1n);
const black = new Array<bigint>(n + 1).fill(1n);
for (let i = order.length - 1; i >= 0; i--) {
  const v = order[i];
  const p = parent[v];
  if (p === -1) continue;
  // 親が白なら子はどちらでもよい。親が黒なら子は白だけ
  white[p] = (white[p] * (white[v] + black[v])) % MOD;
  black[p] = (black[p] * white[v]) % MOD;
}
console.log(((white[1] + black[1]) % MOD).toString());
